`run.mjs`

```js
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { once } from 'node:events';
import fs from 'node:fs/promises';
import { watch as watchDirectory } from 'node:fs';
import net from 'node:net';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
const args = Object.fromEntries(process.argv.slice(2).map((arg) => { const at = arg.indexOf('='); return [arg.slice(0, at), arg.slice(at + 1)]; }));
const repo = path.resolve(args['--repo'] ?? process.cwd());
const expected = args['--expect'] ?? 'fixed';
const sourceLabel = args['--source-label'] ?? 'working-tree';
assert.ok(['main', 'fixed', 'observe'].includes(expected));
const harness = path.dirname(fileURLToPath(import.meta.url));
const root = await fs.mkdtemp(path.join(args['--output-root'] ?? '/tmp', 'warmfork-live-'));
const home = path.join(root, 'home');
const state = path.join(root, 'state');
const workspace = path.join(root, 'workspace');
const bin = path.join(root, 'bin');
await Promise.all([home, state, workspace, bin, path.join(home, '.claude')].map((dir) => fs.mkdir(dir, { recursive: true })));
await fs.writeFile(path.join(bin, 'claude'), `#!${process.execPath}\n${await fs.readFile(path.join(harness, 'fake-claude.cjs'), 'utf8')}`, { mode: 0o755 });
const portServer = net.createServer();
portServer.listen(0, '127.0.0.1');
await once(portServer, 'listening');
const port = portServer.address().port;
await new Promise((resolve, reject) => portServer.close((error) => error ? reject(error) : resolve()));
const configPath = path.join(state, 'openclaw.json');
const modelRef = 'anthropic/claude-sonnet-4-6';
await fs.writeFile(configPath, JSON.stringify({
  agents: { defaults: { workspace, skipBootstrap: true, utilityModel: '', heartbeat: { every: '0m' }, model: { primary: modelRef }, models: { [modelRef]: { agentRuntime: { id: 'claude-cli' } } } }, entries: { main: {} } },
  plugins: { enabled: true, allow: ['anthropic', 'telegram'], entries: { anthropic: { enabled: true, config: { sessionCatalog: { enabled: false } } }, telegram: { enabled: true } }, slots: { memory: 'none' } },
  tools: { profile: 'minimal' },
  logging: { file: path.join(root, 'gateway-runtime.log') },
  gateway: { mode: 'local', port, auth: { mode: 'token', token: 'synthetic-warm-process-token' } },
}, null, 2));
const env = {
  PATH: `${bin}:${process.env.PATH ?? ''}`, HOME: home, TMPDIR: root, LANG: 'C.UTF-8',
  OPENCLAW_STATE_DIR: state, OPENCLAW_CONFIG_PATH: configPath,
  OPENCLAW_PATH_BOOTSTRAPPED: '1', CLAUDE_CONFIG_DIR: path.join(home, '.claude'),
  OPENCLAW_SKIP_CHANNELS: '1', OPENCLAW_SKIP_PROVIDERS: '1', OPENCLAW_SKIP_GMAIL_WATCHER: '1',
  OPENCLAW_SKIP_CRON: '1', OPENCLAW_SKIP_CANVAS_HOST: '1', OPENCLAW_SKIP_BROWSER_CONTROL_SERVER: '1',
  OPENCLAW_TEST_MINIMAL_GATEWAY: '0',
  WARMPROOF_REPO: repo, WARMPROOF_PORT: String(port),
};
// Isolate the client before importing production modules that resolve state paths.
for (const key of Object.keys(process.env)) delete process.env[key];
Object.assign(process.env, env);
const deadline = (promise, ms, label) => {
  let timer;
  return Promise.race([promise, new Promise((_, reject) => timer = setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms))]).finally(() => clearTimeout(timer));
};
const source = (file) => import(pathToFileURL(path.join(repo, file)).href);
const { loadOrCreateDeviceIdentity } = await source('src/infra/device-identity.ts');
const { GatewayClient } = await source('src/gateway/client.ts');
const eventPath = path.join(home, '.claude', 'warm-process-events.jsonl');
const readEvents = async () => (await fs.readFile(eventPath, 'utf8').catch(() => '')).trim().split('\n').filter(Boolean).map(JSON.parse);
let gateway, gatewayExit, gatewayLog, client;
async function startGateway() {
  gatewayLog = await fs.open(path.join(root, 'gateway.log'), 'a');
  gateway = spawn(process.execPath, ['--import', path.join(repo, 'scripts/tsx.mjs'), path.join(harness, 'gateway.mjs')], { cwd: repo, env, stdio: ['ignore', gatewayLog.fd, gatewayLog.fd, 'ipc'] });
  gatewayExit = new Promise((resolve) => gateway.once('exit', (code, signal) => resolve({ code, signal })));
  await deadline(new Promise((resolve, reject) => {
    gateway.on('message', (message) => { if (message?.type === 'ready') resolve(); });
    gateway.once('error', reject);
    gateway.once('exit', (code, signal) => reject(new Error(`Gateway exited during startup: ${code ?? signal}; ${root}/gateway.log`)));
  }), 180_000, 'Gateway startup');
  await deadline(new Promise((resolve, reject) => {
    client = new GatewayClient({
      url: `ws://127.0.0.1:${port}`, token: 'synthetic-warm-process-token',
      clientName: 'test', clientVersion: 'dev', clientDisplayName: 'synthetic-warm-process-proof', mode: 'test',
      deviceIdentity: loadOrCreateDeviceIdentity(), scopes: ['operator.admin', 'operator.read', 'operator.write'],
      onHelloOk: resolve, onConnectError: reject,
    });
    client.start();
  }), 45_000, 'Gateway connect');
}
async function stopGateway() {
  await client?.stopAndWait({ timeoutMs: 3000 });
  client = undefined;
  if (gateway?.connected) gateway.send({ type: 'stop' });
  if (gateway) {
    try { await deadline(gatewayExit, 20_000, 'Gateway shutdown'); }
    catch { gateway.kill('SIGTERM'); await deadline(gatewayExit, 10_000, 'Gateway termination'); }
  }
  gateway = undefined;
  await gatewayLog?.close();
  gatewayLog = undefined;
  let notify;
  const watcher = watchDirectory(path.join(home, '.claude'), () => notify?.());
  try {
    for (;;) {
      const changed = new Promise((resolve) => { notify = resolve; });
      const remaining = new Set();
      for (const event of await readEvents()) {
        if (event.event === 'spawn') remaining.add(event.pid);
        if (event.event === 'exit') remaining.delete(event.pid);
      }
      if (remaining.size === 0) break;
      await deadline(changed, 10_000, 'Owned CLI exit receipts');
    }
  } finally { watcher.close(); }
  console.log(JSON.stringify({ proof: 'cleanup', artifactRoot: root, gatewayExited: true, remainingOwnedCliProcesses: [] }));
}
try {
  await startGateway();
  const sessionKey = `agent:main:warmfork-proof-${randomUUID()}`;
  const acceptedTurns = [];
  let seedEventCount = 0;
  let seededSessionId;
  for (let turn = 0; turn <= 6; turn++) {
    const channelTurn = turn % 2 === 1;
    const method = channelTurn ? 'agent' : 'chat.send';
    const request = { sessionKey, message: `WARMPROOF-TURN-${turn}`, deliver: false, idempotencyKey: randomUUID(), ...(channelTurn ? { channel: 'telegram', accountId: 'proof-account', to: '123456789', timeout: 60 } : {}) };
    const accepted = await client.request(method, request, { timeoutMs: 90_000, ...(channelTurn ? { expectFinal: true } : {}) });
    let completed = accepted;
    if (!channelTurn) completed = await client.request('agent.wait', { runId: accepted.runId, timeoutMs: 60_000 }, { timeoutMs: 70_000 });
    assert.equal(completed.status, 'ok', `${method} turn ${turn} failed: ${JSON.stringify(completed)}`);
    if (turn === 0) {
      console.log(JSON.stringify({ proof: 'seed-complete', status: completed.status }));
      await stopGateway();
      const seedEvents = await readEvents();
      seedEventCount = seedEvents.length;
      seededSessionId = seedEvents.find((event) => event.event === 'turn').sessionId;
      await startGateway();
      continue;
    }
    acceptedTurns.push({ turn, method, accountId: channelTurn ? 'proof-account' : null, status: completed.status });
    console.log(JSON.stringify({ proof: 'turn-complete', ...acceptedTurns.at(-1) }));
  }
  const events = (await readEvents()).slice(seedEventCount);
  assert.ok(events.filter((event) => event.event === 'spawn').every((event) => event.resume), 'Every measured child must use --resume');
  const turns = events.filter((event) => event.event === 'turn');
  assert.equal(turns.length, 6, 'Exactly six user turns must reach native transport');
  assert.deepEqual([...new Set(turns.map((turn) => turn.sessionId))], [seededSessionId], 'All routes must resume the seeded native session');
  assert.deepEqual(turns.map((turn) => turn.marker), acceptedTurns.map((turn) => `WARMPROOF-TURN-${turn.turn}`));
  const active = new Set();
  let maxWarmProcesses = 0;
  for (const event of events) {
    if (event.event === 'spawn') active.add(event.pid);
    if (event.event === 'exit') active.delete(event.pid);
    maxWarmProcesses = Math.max(maxWarmProcesses, active.size);
  }
  const forks = turns.filter((turn) => turn.fork);
  const result = { expected, sourceLabel, sessionKey, nativeSessionId: turns[0].sessionId, gatewayPid: gateway.pid, maxWarmProcesses, finalWarmProcesses: active.size, spawnedProcesses: events.filter((event) => event.event === 'spawn'), forkCount: forks.length, chain: turns.map(({ marker, pid, parent, newest, assistantUuid, fork }) => ({ marker, pid, parent, newest, assistantUuid, fork })), acceptedTurns, artifactRoot: root };
  await fs.writeFile(path.join(root, 'result.json'), JSON.stringify(result, null, 2));
  console.log(JSON.stringify({ proof: 'result', ...result }, null, 2));
  if (expected === 'main') { assert.ok(maxWarmProcesses >= 2, 'Main must show overlapping warm processes'); assert.ok(forks.length > 0, 'Main must show a stale parent'); }
  if (expected === 'fixed') { assert.equal(maxWarmProcesses, 1, 'Fixed must never overlap warm processes'); assert.equal(forks.length, 0, 'Fixed must always extend the newest parent'); }
} catch (error) {
  console.error(`Proof failed; inspect ${root}/gateway.log`);
  throw error;
} finally {
  await stopGateway();
}

```

`gateway.mjs`

```js
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const repo = process.env.WARMPROOF_REPO;
const source = (file) => import(pathToFileURL(path.join(repo, file)).href);
const { loadOrCreateDeviceIdentity, publicKeyRawBase64UrlFromPem } = await source('src/infra/device-identity.ts');
const { getPairedDevice, requestDevicePairing } = await source('src/infra/device-pairing.ts');
const { approveDevicePairing } = await source('src/infra/device-pairing-approval.ts');
const identity = loadOrCreateDeviceIdentity();
const paired = await getPairedDevice(identity.deviceId);
if (!paired) {
const pairing = await requestDevicePairing({
  deviceId: identity.deviceId,
  publicKey: publicKeyRawBase64UrlFromPem(identity.publicKeyPem),
  displayName: 'synthetic-warm-process-proof',
  platform: process.platform,
  clientId: 'test',
  clientMode: 'test',
  role: 'operator',
  scopes: ['operator.admin', 'operator.read', 'operator.write'],
  silent: true,
});
const approved = await approveDevicePairing(pairing.request.requestId, { callerScopes: ['operator.admin'] });
if (approved?.status !== 'approved') throw new Error(`Pairing failed: ${approved?.status}`);
}
const { startGatewayServer } = await source('src/gateway/server.ts');
const server = await startGatewayServer(Number(process.env.WARMPROOF_PORT), {
  bind: 'loopback', auth: { mode: 'token', token: 'synthetic-warm-process-token' }, controlUiEnabled: false,
});
await server.startupSettled;
process.send?.({ type: 'ready' });
let stopping;
const stop = () => stopping ??= server.close({ reason: 'warm-process proof cleanup' }).then(() => process.exit(0));
process.on('message', (message) => { if (message?.type === 'stop') void stop(); });
process.on('SIGTERM', () => void stop());

```

`fake-claude.cjs`

```js
const { randomUUID } = require('node:crypto');
const { appendFileSync, existsSync, mkdirSync, readFileSync } = require('node:fs');
const path = require('node:path');
const { createInterface } = require('node:readline');
const root = process.env.CLAUDE_CONFIG_DIR;
const send = (message) => process.stdout.write(JSON.stringify(message) + '\n');
if (process.argv.includes('--version')) {
  console.log('2.1.226 (Claude Code synthetic warm-process proof)');
  process.exit(0);
}
if (process.argv.includes('auth')) {
  send({ loggedIn: true, authMethod: 'claude.ai', email: 'fixture@example.invalid' });
  process.exit(0);
}
const resumeIndex = process.argv.indexOf('--resume');
const sessionIndex = resumeIndex >= 0 ? resumeIndex : process.argv.indexOf('--session-id');
if (sessionIndex < 0) throw new Error('No native session identity supplied');
const sessionId = process.argv[sessionIndex + 1];
const workspace = process.cwd().normalize('NFC');
let projectKey = workspace.replace(/[^a-zA-Z0-9]/g, '-');
if (projectKey.length > 200) {
  let hash = 0;
  for (let index = 0; index < workspace.length; index++) hash = (hash * 31 + workspace.charCodeAt(index)) >>> 0;
  projectKey = `${projectKey.slice(0, 200)}-${hash.toString(36)}`;
}
const project = path.join(root, 'projects', projectKey);
mkdirSync(project, { recursive: true });
const transcript = path.join(project, `${sessionId}.jsonl`);
const evidence = path.join(root, 'warm-process-events.jsonl');
const rows = () => existsSync(transcript) ? readFileSync(transcript, 'utf8').trim().split('\n').filter(Boolean).map(JSON.parse) : [];
let leaf = resumeIndex >= 0 ? rows().at(-1)?.uuid ?? null : null;
const record = (event) => appendFileSync(evidence, JSON.stringify({ ...event, pid: process.pid, sessionId }) + '\n');
record({ event: 'spawn', resume: resumeIndex >= 0, resumeParent: leaf });
process.on('exit', () => record({ event: 'exit' }));
process.on('SIGTERM', () => process.exit(0));
createInterface({ input: process.stdin }).on('line', (line) => {
  const message = JSON.parse(line);
  if (message.type === 'control_request') {
    send({ type: 'control_response', response: { subtype: 'success', request_id: message.request_id, response: { commands: [], models: [] } } });
    return;
  }
  if (message.type !== 'user') return;
  const text = typeof message.message.content === 'string' ? message.message.content : JSON.stringify(message.message.content);
  const marker = text.match(/WARMPROOF-TURN-\d+/)?.[0];
  if (!marker) throw new Error('Unexpected non-proof user turn');
  const userUuid = message.uuid ?? randomUUID();
  const assistantUuid = randomUUID();
  const newest = rows().at(-1)?.uuid ?? null;
  const reply = `${marker} pid=${process.pid} parent=${leaf ?? 'root'}`;
  record({ event: 'turn', marker, parent: leaf, newest, userUuid, assistantUuid, fork: leaf !== newest });
  const assistantMessage = { role: 'assistant', content: [{ type: 'text', text: reply }] };
  for (const row of [
    { type: 'user', uuid: userUuid, parentUuid: leaf, message: message.message },
    { type: 'assistant', uuid: assistantUuid, parentUuid: userUuid, message: assistantMessage },
  ]) appendFileSync(transcript, JSON.stringify({ ...row, sessionId, cwd: workspace, timestamp: new Date().toISOString(), isSidechain: false }) + '\n');
  leaf = assistantUuid;
  send({ type: 'assistant', uuid: assistantUuid, session_id: sessionId, message: assistantMessage });
  send({ type: 'result', subtype: 'success', is_error: false, result: reply, session_id: sessionId, duration_ms: 1, duration_api_ms: 1, num_turns: 1, total_cost_usd: 0, usage: {}, modelUsage: {}, permission_denials: [] });
});

